const uint8_t* fontGlyph(char c) {
  if (c >= 'a' && c <= 'z') {
    c = (char)(c - ('a' - 'A'));
  }
  uint8_t index = 0;
  if ((uint8_t)c >= 32 && (uint8_t)c <= 90) {
    index = (uint8_t)((uint8_t)c - 32);
  }
  return GLYPHS + (uint16_t)index * 5;
}
